
class B1Question {
  const B1Question(this.prompt, this.options, this.answer, this.explanation);
  final String prompt;
  final List<String> options;
  final int answer;
  final String explanation;
}

class B1Lesson {
  const B1Lesson({
    required this.unitId, required this.globalNumber, required this.title,
    required this.goal, required this.rule, required this.examples,
    required this.dialogue, required this.speakingTask, required this.questions,
  });
  final String unitId;
  final int globalNumber;
  final String title, goal, rule, dialogue, speakingTask;
  final List<String> examples;
  final List<B1Question> questions;
  int get lessonNumber => (globalNumber - (unitId == 'b1-u1' ? 120 : unitId == 'b1-u2' ? 130 : unitId == 'b1-u3' ? 140 : unitId == 'b1-u4' ? 150 : unitId == 'b1-u5' ? 160 : unitId == 'b1-u6' ? 170 : unitId == 'b2-u1' ? 180 : unitId == 'b2-u2' ? 190 : unitId == 'b2-u3' ? 200 : unitId == 'b2-u4' ? 210 : unitId == 'b2-u5' ? 220 : 230));
}

class B1CourseData {
  static List<String> _rotate(List<String> options, int answerIndex) => List<String>.generate(
    options.length,
    (index) => options[(index - answerIndex + options.length) % options.length],
  );

  static B1Question _q(String p, List<String> o, String why, int answer) =>
      B1Question(p, o, answer, why);
  static B1Lesson _lesson({
    required String unitId, required int number, required String title,
    required String goal, required String rule, required String term,
    required String meaning, required String sentence, required String translation,
    required String form, required String formMeaning, required String function,
    required List<String> wordChoices, required List<String> sentenceChoices,
    required List<String> formChoices, required List<String> functionChoices,
    required List<String> examples, required String dialogue, required String task,
  }) => B1Lesson(
    unitId: unitId, globalNumber: number, title: title, goal: goal, rule: rule,
    examples: examples, dialogue: dialogue, speakingTask: task,
    questions: [
      _q('ما معنى «$term»؟', _rotate(wordChoices, number % 4), '$term تعني $meaning.', number % 4),
      _q('ما ترجمة الجملة: «$sentence»؟', _rotate(sentenceChoices, (number + 1) % 4), '$sentence تعني $translation.', (number + 1) % 4),
      _q('اختر الصيغة الصحيحة المرتبطة بالقاعدة:', _rotate(formChoices, (number + 2) % 4), '$formMeaning.', (number + 2) % 4),
      _q('ما الوظيفة النحوية للتعبير «$form»؟', _rotate(functionChoices, (number + 3) % 4), '$function', (number + 3) % 4),
      _q('أكمل التركيب: $sentence', _rotate(formChoices, (number + 1) % 4), 'الصيغة المستهدفة هي $form؛ $formMeaning.', (number + 1) % 4),
    ],
  );

